# NDK library: export the public C API declared in net_ethernet.h, plus
# the inline singleton definitions instantiated from netmanager_base NDK
# headers (NetConnClient::instance_/instanceMtx_ and the DelayedSingleton
# members/guards of EthernetClient). App side may reference them after
# header expansion, so they must stay exported. Internal helpers
# (FillNetAddrListFromEthernet/CopyStrToBuffer/ConvertErrorCode) are
# file-local and hidden.
{
  global:
    OH_Ethernet_GetMacAddress;
    OH_Ethernet_GetNetAddress;
    _ZN4OHOS18NetManagerStandard13NetConnClient9instance_E;
    _ZN4OHOS18NetManagerStandard13NetConnClient12instanceMtx_E;
    _ZN4OHOS16DelayedSingletonINS_18NetManagerStandard14EthernetClientEE9instance_E;
    _ZN4OHOS16DelayedSingletonINS_18NetManagerStandard14EthernetClientEE6mutex_E;
    _ZGVN4OHOS18NetManagerStandard13NetConnClient9instance_E;
    _ZGVN4OHOS18NetManagerStandard13NetConnClient12instanceMtx_E;
    _ZGVN4OHOS16DelayedSingletonINS_18NetManagerStandard14EthernetClientEE9instance_E;
    _ZGVN4OHOS16DelayedSingletonINS_18NetManagerStandard14EthernetClientEE6mutex_E;
  local:
    *;
};
